-- Isolated fixtures and assertions: every change rolls back, including auth users.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select plan(34);
create temp table tap_results(result text);
grant insert,select on tap_results to anon,authenticated;
create temp table ids(k text primary key,id uuid not null);
grant select on ids to anon,authenticated;
set local role anon;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='x'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='a'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='b'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='a'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='b'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='a'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='s'),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select id from ids where k='t'),'role','authenticated')::text,true);
set local role authenticated;
select public.save_my_availability('2026-11-01 14:00Z','2026-11-01 19:00Z',array[]::text[]);
reset role;
select json_build_object('assertions',count(*),'failures',count(*) filter(where result not like 'ok %'),'results',json_agg(result)) as security_test_results from tap_results;
rollback;
